import{_ as o,o as e,c as d,aj as a}from"./framework.js";const b=JSON.parse('{"title":"Kooboo CLI | Cli | Documentation","description":"Kooboo CLI 是 Kooboo 的本地开发工具。它把站点资源保存为本地文件，并提供创建或克隆项目、拉取资源、推送改动、Git 产物部署、持续同步、资源对账和站点导出等工作流。","frontmatter":{"title":"Kooboo CLI | Cli | Documentation","description":"Kooboo CLI 是 Kooboo 的本地开发工具。它把站点资源保存为本地文件，并提供创建或克隆项目、拉取资源、推送改动、Git 产物部署、持续同步、资源对账和站点导出等工作流。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cli/index.html"}]]},"headers":[],"relativePath":"zh/cli/index.md","filePath":"cli/index.md","lastUpdated":1787220900000}'),l={name:"zh/cli/index.md"};function i(r,t,c,s,h,n){return e(),d("div",null,[...t[0]||(t[0]=[a(`<h1 id="kooboo-cli" tabindex="-1">Kooboo CLI <a class="header-anchor" href="#kooboo-cli" aria-label="Permalink to &quot;Kooboo CLI&quot;">​</a></h1><p>Kooboo CLI 是 Kooboo 的本地开发工具。它把站点资源保存为本地文件，并提供创建或克隆项目、拉取资源、推送改动、Git 产物部署、持续同步、资源对账和站点导出等工作流。</p><p>完整命令名是 <code>kooboo-cli</code>，日常可以使用缩写 <code>kb</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kooboo-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><h2 id="主要能力" tabindex="-1">主要能力 <a class="header-anchor" href="#主要能力" aria-label="Permalink to &quot;主要能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>命令</th><th>适用场景</th></tr></thead><tbody><tr><td>创建站点项目</td><td><code>kb new</code></td><td>新建远程站点并生成本地项目</td></tr><tr><td>克隆已有站点</td><td><code>kb clone</code></td><td>将已有 Kooboo 站点资源拉到本地维护</td></tr><tr><td>拉取资源</td><td><code>kb pull</code></td><td>获取远端最新资源或只刷新指定范围</td></tr><tr><td>推送资源</td><td><code>kb push</code></td><td>将本地资源写入远端站点</td></tr><tr><td>部署 Git 产物</td><td><code>kb deploy</code></td><td>按 commit 范围计划、执行并校验正式发布</td></tr><tr><td>持续同步</td><td><code>kb sync</code></td><td>监听本地文件变化并实时写入远端</td></tr><tr><td>资源对账</td><td><code>kb check</code></td><td>比较本地与远端的资源差异</td></tr><tr><td>清理远端漂移</td><td><code>kb prune</code></td><td>审计并显式清理非发布流程产生的仅远端资源</td></tr><tr><td>导出站点</td><td><code>kb export</code></td><td>选择资源并下载站点压缩包</td></tr></tbody></table><h2 id="推荐学习路径" tabindex="-1">推荐学习路径 <a class="header-anchor" href="#推荐学习路径" aria-label="Permalink to &quot;推荐学习路径&quot;">​</a></h2><ol><li>阅读<a href="./getting-started/preparation.html">使用前准备</a>，配置目标站点和登录信息。</li><li>根据情况<a href="./getting-started/create-or-clone.html">新建或克隆项目</a>。</li><li>了解<a href="./project/resources.html">项目资源与目录</a>。</li><li>使用 <a href="./workflows/pull.html"><code>kb pull</code></a> 获取远端改动。</li><li>使用 <a href="./workflows/push.html"><code>kb push</code></a> 发布本地改动。</li><li>正式发布不可变产物时，使用 <a href="./workflows/deploy.html"><code>kb deploy</code></a>。</li><li>确实需要远端实时联调时，再使用 <a href="./workflows/sync.html"><code>kb sync</code></a>。</li></ol><h2 id="先理解远端影响" tabindex="-1">先理解远端影响 <a class="header-anchor" href="#先理解远端影响" aria-label="Permalink to &quot;先理解远端影响&quot;">​</a></h2><p><code>kb pull</code> 会把远端内容写入本地项目。<code>kb push</code>、<code>kb deploy</code>、<code>kb sync</code> 和带 <code>--yes</code> 的 <code>kb prune</code> 会修改远端站点。</p><p>执行这些命令前，先确认当前目录、<code>.env</code> 中的站点地址以及准备操作的资源范围。团队项目中建议先提交或保存本地改动，再执行可能覆盖文件的拉取操作。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./getting-started/preparation.html">使用前准备</a></li><li><a href="./getting-started/create-or-clone.html">新建或克隆项目</a></li><li><a href="./troubleshooting.html">常见问题</a></li></ul>`,13)])])}const k=o(l,[["render",i]]);export{b as __pageData,k as default};
